$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
$r=Join-Path $env:TEMP 'oe-idle-tls-r2-build-773e34c7-06b9a13'
$expected=''
$matches=@(Get-CimInstance Win32_Process|Where-Object {$_.Name -eq 'powershell.exe' -and $_.CommandLine -and $_.CommandLine.EndsWith($expected)})
$files=@(Get-ChildItem -LiteralPath $r -Force)
$record=[ordered]@{recorded_utc=[DateTime]::UtcNow.ToString('o');exact_setup_command_match_count=$matches.Count;owned_root_item_names=@($files|ForEach-Object {$_.Name});build_guard_exists=(Test-Path -LiteralPath (Join-Path $r 'build-once.guard'));payload_exists=(Test-Path -LiteralPath (Join-Path $r 'payload.tar'));stop_requested=$false;reason='Only the exact owned setup process may be stopped, before payload/build start.'}
if($matches.Count -eq 1){$m=$matches[0];$p=Get-Process -Id $m.ProcessId;$record.setup=[ordered]@{pid=$m.ProcessId;created_utc=$m.CreationDate.ToUniversalTime().ToString('o');elapsed_seconds=([DateTime]::UtcNow-$m.CreationDate.ToUniversalTime()).TotalSeconds;cpu_seconds=$p.CPU;priority=$p.PriorityClass.ToString();session=$p.SessionId};if(-not $record.build_guard_exists -and -not $record.payload_exists -and $files.Count -eq 0 -and $record.setup.elapsed_seconds -gt 120){Stop-Process -Id $m.ProcessId -ErrorAction Stop;$record.stop_requested=$true;$record.stop_reason='Source-transfer setup remained before payload write for more than 120 seconds. Preserve the first attempt; no build retry.'}}
$record|ConvertTo-Json -Depth 8 -Compress
